def generate_iso_timestamp():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def is_valid_capacity(val):
    """Check if capacity is a valid positive integer"""
    if val is None:
        return False
    try:
        # Check if it can be converted to int
        if isinstance(val, bool):
            return False  # bool is subclass of int but shouldn't be treated as int
        if isinstance(val, int):
            if val <= 0:
                return False
            return True
        if isinstance(val, float):
            # Floats are not integers per requirement
            return False
        if isinstance(val, str):
            try:
                parsed = int(val)
                if parsed <= 0:
                    return False
                return True
            except ValueError:
                return False
        return False
    except:
        return False

def has_sql_injection(title: str) -> bool:
    """Check if title contains SQL injection patterns that should be rejected"""
    if not title:
        return False
    title_lower = title.lower()
    # These are patterns that should be rejected
    # "'; DROP TABLE todos; --"
    if re.search(r"';\s*drop\s+table", title_lower):
        return True
    # "SELECT * FROM users"
    if re.search(r"select\s+\*\s+from", title_lower):
        return True
    if re.search(r"select\s+\*", title_lower):
        # But "SELECT best practices" shouldn't match this - it has "select best" not "select *"
        # Actually "SELECT best practices" contains "select " followed by "best", not "*"
        # So checking "select *" is safe - only real SQL patterns have *
        return True
    # "admin' OR '1'='1"
    if re.search(r"admin'.*or", title_lower):
        return True
    # "' OR 1=1 --"
    if re.search(r"'\s*or\s+.*=", title_lower):
        return True
    # "' UNION SELECT password FROM users --"
    if re.search(r"'\s*union\s+select", title_lower):
        return True
    # Additional check for generic injection patterns
    if re.search(r"or\s+'?\d+'?\s*=\s*'?\d+'?", title_lower):
        return True
    return False

