@app.route('/todos', methods=['GET'])
def get_todos():
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team = teams[x_team_id]

    # Parse query parameters
    page = request.args.get('page')
    sort = request.args.get('sort', 'created_asc')
    completed_filter = request.args.get('completed')
    tag_filter = request.args.get('tag')

    # Validate page
    try:
        page_int = int(page) if page else 1
        if page_int <= 0:
            return jsonify({"error": "Bad request"}), 400
    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    page = page_int

    # Get all todos for this team
    todos_list = list(team.todos.values())

    # Apply filters
    if completed_filter is not None:
        completed_val = completed_filter.lower() == 'true'
        todos_list = [t for t in todos_list if t.get('completed') == completed_val]

    if tag_filter:
        tag_val = tag_filter
        todos_list = [t for t in todos_list if tag_val in t.get('tags', [])]

    # Apply sorting
    if sort == 'created_desc':
        todos_list.sort(key=lambda t: t.get('created_at', ''), reverse=True)
    elif sort == 'title':
        todos_list.sort(key=lambda t: t.get('title', ''))
    # Default is created_asc - already in insertion order probably

    # Pagination - max 50 per page
    page_size = min(50, len(todos_list))
    start_idx = (page - 1) * 50
    end_idx = start_idx + page_size

    paginated_todos = todos_list[start_idx:end_idx]

    # Calculate next_cursor - if there are more items after this page
    remaining = len(todos_list) - end_idx
    next_cursor = page + 1 if remaining > 0 else None

    response = {
        "todos": paginated_todos,
        "page": page,
        "page_size": 50,  # The max page size constant
        "next_cursor": next_cursor,
        "total": len(todos_list)
    }
    return jsonify(response), 200

@app.route('/todos', methods=['POST'])
def create_todo():
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

