@app.route('/todos/<int:todo_id>', methods=['PUT'])
def update_todo(todo_id):
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team = teams[x_team_id]

