    except ValueError:
        return jsonify({"error": "Bad request"}), 400

    # Check if team owns this todo
    if todo_id not in team.todos:
        return jsonify({"error": "Todo not found"}), 404

    current_todo = team.todos[todo_id]
    if current_todo['version'] != provided_version:
        response = {
            "error": "Version mismatch",
            "current_version": current_todo['version'],
            "provided_version": provided_version
        }
        return jsonify(response), 409

    # Update the todo
    now = generate_iso_timestamp()
    # Only update provided fields
    data = request.get_json(force=True)
    if not data:
        data = {}

    updated_todo = dict(current_todo)
    if 'title' in data:
        updated_todo['title'] = data['title']
    if 'completed' in data:
        updated_todo['completed'] = data['completed']
    if 'tags' in data:
        updated_todo['tags'] = data['tags']
    if 'metadata' in data:
        updated_todo['metadata'] = data['metadata']
    updated_todo['version'] = current_todo['version'] + 1
    updated_todo['updated_at'] = now

    team.todos[todo_id] = updated_todo

    return jsonify(updated_todo), 200

@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team = teams[x_team_id]

    if todo_id not in team.todos:
        return jsonify({"error": "Todo not found"}), 404

    del team.todos[todo_id]
    return jsonify({"id": todo_id, "deleted": True}), 200

@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

