    except Exception:
        return jsonify({"error": "Bad request"}), 400

    if not json_data:
        return jsonify({"error": "Bad request"}), 400

    if 'updates' not in json_data:
        return jsonify({"error": "Bad request"}), 400

    updates = json_data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400

    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    # Validate each update item
    for i, update in enumerate(updates):
        if not isinstance(update, dict):
            return jsonify({"error": "Bad request"}), 400
        if 'id' not in update:
            return jsonify({"error": "Bad request"}), 400
        # Validate title if provided
        if 'title' in update:
            title = update['title']
            if not isinstance(title, str):
                return jsonify({"error": "Bad request"}), 400
            if not title.strip():
                return jsonify({"error": "Bad request"}), 400
            if len(title) > 1000:
                return jsonify({"error": "Bad request"}), 400
            if has_sql_injection(title):
                return jsonify({"error": "Bad request"}), 400

    # All validations passed - check if all todos exist in team
    # Atomic - all or nothing
    failed = False
    updated_items = []

    # First check if all referenced todos belong to this team and exist
    existing_ids = set()
    for update in updates:
        tid = update['id']
        if tid not in team.todos:
            failed = True
            break
        existing_ids.add(tid)

    if failed:
        # Rollback - don't update anything
        return jsonify({"updated": [], "count": 0}), 404

    # Actually wait - the spec says:
    # "Batch contains updates for todo ID 1 (exists) and todo ID 99999 (doesn't exist)"
    # "Expected behavior: Entire batch fails with 404 Not Found"
    # "Todo ID 1 is NOT updated (rollback)"
    # So if any todo doesn't exist, return 404 with empty updated array

    # Also validation failure returns 400 with no updates
    # So we first validate everything (title validation etc)
    # Then check existence
    # If any validation fails -> 400, no updates
    # If any doesn't exist -> 404, no updates
    # If all exist and valid -> apply all updates and return 200 with results

    # Let me re-read batch requirements:
    # 6.3 Validation Failure in Batch - returns 400, no todos updated
    # 6.2 Atomic Failure - returns 404, no todos updated
    # 6.5 Empty batch - returns 200 with empty updated array

    # So the flow is:
    # 1. Validate structure (updates is array, each item is object with id)
    # 2. Validate each update content (title rules, etc) - if fail -> 400
    # 3. Check if all target todos exist for this team - if any missing -> 404
    # 4. Apply all updates -> 200

    # Let me implement this order

    # Check updates structure first
    if 'updates' not in json_data:
        return jsonify({"error": "Bad request"}), 400
    updates = json_data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400
    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    # Validate each update item structure
    for update in updates:
        if not isinstance(update, dict):
            return jsonify({"error": "Bad request"}), 400
        if 'id' not in update:
            return jsonify({"error": "Bad request"}), 400

    # Validate content of each update (title validation if title is being updated)
    # Actually - the update might only provide partial fields. We need to validate what's being changed?
    # Looking at example: {"id": 1, "title": "Updated 1"} - title is being set to new value
    # So we validate the new title value against rules
    for update in updates:
        if 'title' in update:
            title = update['title']
            if not isinstance(title, str):
                return jsonify({"error": "Bad request"}), 400
            if not title.strip():
                return jsonify({"error": "Bad request"}), 400
            if len(title) > 1000:
                return jsonify({"error": "Bad request"}), 400
            if has_sql_injection(title):
                return jsonify({"error": "Bad request"}), 400
        # For tags and metadata, what validation? The spec says:
        # - tags must be array of strings
        # - metadata must be object
        if 'tags' in update:
            tags = update['tags']
            if not isinstance(tags, list):
                return jsonify({"error": "Bad request"}), 400
            for tag in tags:
                if not isinstance(tag, str):
                    return jsonify({"error": "Bad request"}), 400
        if 'metadata' in update:
            metadata = update['metadata']
            if not isinstance(metadata, dict):
                return jsonify({"error": "Bad request"}), 400

    # Now check existence of all todos in the team
    all_exist = True
    for update in updates:
        tid = update['id']
        if tid not in team.todos:
            all_exist = False
            break

    if not all_exist:
        return jsonify({"updated": [], "count": 0}), 404

    # Apply all updates
    updated_list = []
    for update in updates:
        tid = update['id']
        todo = team.todos[tid]
        new_todo = dict(todo)
        if 'title' in update:
            new_todo['title'] = update['title']
        if 'completed' in update:
            new_todo['completed'] = update['completed']
        if 'tags' in update:
            new_todo['tags'] = update['tags']
        if 'metadata' in update:
            new_todo['metadata'] = update['metadata']
        new_todo['version'] = todo['version'] + 1
        new_todo['updated_at'] = generate_iso_timestamp()
        team.todos[tid] = new_todo
        updated_list.append(new_todo)

    return jsonify({"updated": updated_list, "count": len(updates)}), 200

@app.route('/todos/export', methods=['GET'])
def export_todos():
    # Check X-Team-ID header
    x_team_id = request.headers.get('X-Team-ID')
    if not x_team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    if x_team_id not in teams:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team = teams[x_team_id]

    snapshot_id = str(uuid.uuid4())
    todo_count = len(team.todos)

    response = {
        "snapshot_id": snapshot_id,
        "message": "Snapshot created for team",
        "todo_count": todo_count
    }
    return jsonify(response), 200

